    INSERT INTO [dbo].[AIKnowledgeEntries] ([Id], [Title], [Content], [Category], [Keywords], [IsActive], [DisplayOrder], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES (1, N'Giao hàng & lắp đặt', N'Phí giao hàng và lắp đặt không tính sẵn trên website: sau khi khách gửi yêu cầu đặt hàng, cửa hàng gọi lại và báo phí theo địa chỉ, số món và tầng lầu. Nội thành thường giao trong 2 - 4 ngày, các tỉnh 3 - 7 ngày. Đồ đặt đóng theo yêu cầu cần thêm thời gian sản xuất, cửa hàng báo cụ thể khi xác nhận.', N'Chính sách', N'giao hàng, vận chuyển, ship, lắp đặt, phí giao, bao lâu, mấy ngày', 1, 1, '2026-10-06T19:21:23.8147449', N'system', NULL, NULL);
    INSERT INTO [dbo].[AIKnowledgeEntries] ([Id], [Title], [Content], [Category], [Keywords], [IsActive], [DisplayOrder], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES (2, N'Bảo hành', N'Thời gian bảo hành ghi trong mục Thông số của từng sản phẩm (phần lớn 12 - 24 tháng) cho khung, kết cấu và lỗi sản xuất. Không bảo hành hư hỏng do sử dụng sai cách, ngâm nước hoặc va đập. Liên hệ hotline hoặc chat để được hỗ trợ bảo hành.', N'Chính sách', N'bảo hành, sửa chữa, hỏng, lỗi, bảo trì', 1, 2, '2026-10-06T19:21:23.8147449', N'system', NULL, NULL);
    INSERT INTO [dbo].[AIKnowledgeEntries] ([Id], [Title], [Content], [Category], [Keywords], [IsActive], [DisplayOrder], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES (3, N'Đổi trả', N'Đổi trả trong 7 ngày nếu sản phẩm lỗi do sản xuất hoặc giao sai mẫu. Hàng đặt đóng theo kích thước riêng không áp dụng đổi trả vì lý do cá nhân.', N'Chính sách', N'đổi trả, trả hàng, hoàn tiền, đổi hàng', 1, 3, '2026-10-06T19:21:23.8147449', N'system', NULL, NULL);
    INSERT INTO [dbo].[AIKnowledgeEntries] ([Id], [Title], [Content], [Category], [Keywords], [IsActive], [DisplayOrder], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES (4, N'Thanh toán', N'Website nhận yêu cầu đặt hàng, không thanh toán trực tuyến. Sau khi cửa hàng liên hệ xác nhận mẫu, giá và phí giao - lắp đặt, khách thanh toán khi nhận hàng (COD) hoặc chuyển khoản theo hướng dẫn của nhân viên, nội dung ghi mã đơn hàng.', N'Chính sách', N'thanh toán, chuyển khoản, cod, trả tiền, trả góp, cọc', 1, 4, '2026-10-06T19:21:23.8147449', N'system', NULL, NULL);
    INSERT INTO [dbo].[AIKnowledgeEntries] ([Id], [Title], [Content], [Category], [Keywords], [IsActive], [DisplayOrder], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES (5, N'Đặt đóng theo yêu cầu', N'Xưởng Nhà Mộc nhận đóng nội thất theo kích thước, chất liệu và màu khách chọn. Khách có thể nhận báo giá dự kiến ở trang Báo giá; giá cuối cùng do cửa hàng xác nhận sau khi trao đổi chi tiết.', N'Dịch vụ', N'đặt đóng, theo yêu cầu, custom, kích thước riêng, báo giá, thiết kế riêng', 1, 5, '2026-10-06T19:21:23.8147449', N'system', NULL, NULL);
    INSERT INTO [dbo].[AIKnowledgeEntries] ([Id], [Title], [Content], [Category], [Keywords], [IsActive], [DisplayOrder], [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy]) VALUES (6, N'Bảo quản đồ gỗ', N'Lau bằng khăn mềm hơi ẩm rồi lau khô, tránh hóa chất tẩy mạnh; không đặt đồ gỗ sát nguồn nhiệt hoặc nơi nắng gắt; dùng lót cốc cho mặt bàn; đồ bọc vải nên hút bụi định kỳ.', N'Hỏi đáp', N'bảo quản, vệ sinh, lau chùi, chăm sóc, mối mọt', 1, 6, '2026-10-06T19:21:23.8147449', N'system', NULL, NULL);
